   "id": "z708bf74e",
   "sez": "prima",
   "titolo": "Gli inviati Usa arrivano a Mosca per colloqui con Putin sull'Ucraina",
   "orig": "US envoys arrive in Moscow for Ukraine talks with Vladimir Putin",
   "lead": "Gli inviati statunitensi Jared Kushner e Steve Witkoff sono arrivati giovedì a Mosca per incontrare il presidente russo Vladimir Putin, nel tentativo di individuare un'intesa sulla guerra in Ucraina. L'incontro arriva dopo due giorni di colloqui trilaterali ad Abu Dhabi tra Stati Uniti, Ucraina ed europei. Nel pomeriggio gli stessi inviati si sposteranno a Dublino per vedere il presidente ucraino Volodymyr Zelensky, mentre a Mosca si cerca uno spiraglio per fermare il conflitto che dura da quasi quattro anni.",
   "more": [
    "Kushner e Witkoff sono emissari dell'amministrazione Trump impegnati da mesi in una mediazione tra Mosca e Kiev. I negoziati arrivano dopo anni di combattimenti senza una soluzione diplomatica stabile, con gli alleati europei preoccupati di essere esclusi da un eventuale accordo sul futuro dell'Ucraina."
   ],
