   "titolo": "Maltempo in Toscana, esondano fiumi a Massa e in Lunigiana",
   "orig": "Maltempo in Toscana, esondano fiumi e torrenti a Massa e in Lunigiana. Serchio in piena, sfollati",
   "lead": "Il maltempo che ha colpito la Toscana ha causato l'esondazione di fiumi e torrenti nelle zone di Massa e della Lunigiana, con il fiume Frigido e il torrente Bardine usciti dagli argini. Nella zona di Lucca il fiume Serchio in piena ha invaso una strada statale, costringendo all'evacuazione di alcuni residenti. La Regione ha mantenuto l'allerta rossa fino alla mezzanotte di giovedì 12 novembre. Lo riferisce la Repubblica.",
