   "id": "z36dd653b",
   "sez": "mondo",
   "titolo": "La 'arma segreta' di Trump per controllare le università diventa realtà",
   "orig": "Trump proposed a 'secret weapon' to police colleges. It will soon become reality",
   "lead": "Il Dipartimento dell'Istruzione statunitense ha finalizzato una norma che permetterà all'amministrazione Trump di intervenire sulle università americane, realizzando una promessa fatta dal presidente in un discorso elettorale del 2023 in cui si impegnava a 'riprendere' gli atenei da quella che definiva la 'sinistra radicale'. Lo riferisce NPR.",
   "more": [
    "Negli ultimi anni diverse amministrazioni statunitensi hanno cercato di influenzare le politiche interne delle università, spesso legando finanziamenti federali al rispetto di determinate regole su diversità, assunzioni o programmi accademici. Le nuove norme rientrano in questo filone di intervento federale sull'istruzione superiore."
   ],
