   "id": "z620e899e",
   "sez": "ambiente",
   "titolo": "In calo nei fiumi inglesi i livelli delle sostanze chimiche tossiche 'eterne'",
   "orig": "Significant drop in levels of toxic 'forever' chemicals in England's rivers",
   "lead": "I livelli di sostanze chimiche 'per sempre', note per la loro persistenza nell'ambiente e potenzialmente tossiche, sono diminuiti in modo significativo nei fiumi d'Inghilterra. Il calo viene attribuito alle severe restrizioni introdotte sull'uso di queste sostanze negli ultimi anni. Lo riferisce BBC News.",
   "more": [
    "Le sostanze 'forever chemicals' (PFAS) sono composti chimici usati per decenni in prodotti industriali e di consumo, difficili da degradare in natura. Studi recenti ne hanno collegato l'esposizione prolungata a diversi rischi per la salute, incluse forme aggressive di tumore, spingendo diversi Paesi a limitarne progressivamente l'impiego."
   ],
