   "id": "z3f023b1f",
   "sez": "salute",
   "titolo": "Yvette Cooper annuncia un nuovo ente del NHS dopo l'abolizione del 'più grande quango del mondo'",
   "orig": "Yvette Cooper unveils new NHS quango as part of abolishing &#x201C;world&#x2019;s largest quango&#x201D;",
   "lead": "La ministra britannica della Salute Yvette Cooper ha confermato la creazione di un nuovo organismo del servizio sanitario nazionale inglese, separato dal Dipartimento della Salute e dell'Assistenza Sociale, per occuparsi del lavoro regionale precedentemente svolto da NHS England. L'annuncio segue la decisione, presa lo scorso anno dal governo, di abolire NHS England, definito dall'ex premier Keir Starmer 'il più grande quango del mondo', nel tentativo di eliminare una doppia struttura burocratica. Lo riferisce The BMJ.",
   "more": [
    "Un 'quango' nel Regno Unito è un organismo quasi-governativo, finanziato con fondi pubblici ma operante con una certa autonomia dal governo. NHS England gestiva gran parte dell'organizzazione del servizio sanitario inglese; la sua abolizione, annunciata per semplificare la burocrazia, si è rivelata complessa da attuare nella pratica."
   ],
