   "id": "z1bf70f6a",
   "sez": "prima",
   "titolo": "La BBC al fianco di un'unità di drone ucraina a difesa di una città in prima linea",
   "orig": "'If I tell you to run, run': BBC joins a Ukrainian drone unit as it protects a front-line city",
   "lead": "Giornalisti della BBC hanno seguito un'unità di drone ucraina impegnata nella difesa di Slovyansk, città del fronte orientale continuamente bombardata dalle forze russe e ormai quasi disabitata, con meno del 10% della popolazione prebellica rimasta. La stessa unità ha sviluppato tecniche pionieristiche di evacuazione tramite drone, utilizzate per recuperare i feriti sotto il fuoco nemico, e ora sta ampliando queste operazioni su scala più vasta nella regione di Kharkiv.",
   "more": [
    "Le forze ucraine utilizzano sempre più spesso drone per compiti che vanno dalla ricognizione agli attacchi, fino alle evacuazioni di soldati feriti in zone troppo pericolose per i mezzi convenzionali. Slovyansk è una delle città simbolo della resistenza ucraina nel Donbass, teatro di combattimenti intensi fin dalle prime fasi dell'invasione russa del 2022."
   ],
