   "lead": "Il capitano della nazionale di cricket australiana Mitch Marsh ha evitato di rispondere alle domande sullo scandalo 'Sandpapergate' del 2018, relativo al tour in Sudafrica, durante uno scambio teso con i giornalisti in conferenza stampa. Lo riferisce ABC News Australia.",
