    "Il 'Sandpapergate' è lo scandalo di manomissione della palla che nel 2018 coinvolse la nazionale australiana di cricket durante un tour in Sudafrica, con pesanti sanzioni per alcuni giocatori e un duro colpo all'immagine della squadra, episodio ancora oggetto di attenzione mediatica anni dopo."
