   "sez": "economia",
   "titolo": "Le sanzioni della SEC contro le aziende quotate ai minimi da 16 anni",
   "orig": "Wall Street watchdog enforcement against public companies drops to 16-year low",
   "lead": "La Securities and Exchange Commission, l'autorità di vigilanza dei mercati statunitensi, ha avviato il minor numero di azioni contro società quotate almeno dal 2010, secondo un nuovo rapporto. Il calo segna un livello di applicazione delle regole ai minimi da 16 anni. Lo riferisce Financial Times.",
   "more": [
    "La SEC è l'organo federale statunitense che vigila sui mercati finanziari e sulle società quotate in borsa, con poteri di indagine e sanzione per frodi finanziarie, insider trading e violazioni delle norme di trasparenza. Un calo delle azioni di enforcement può riflettere cambiamenti di priorità politica o di risorse dell'ente."
   ],
