   "titolo": "La sonda Hera si avvicina all'asteroide colpito dalla missione DART",
   "orig": "Hera closes in on the asteroid DART impacted",
   "lead": "La sonda Hera dell'Agenzia spaziale europea (ESA) ha trasmesso le prime immagini da distanza ridotta del sistema di asteroidi Didymos, dando inizio a una fase di analisi dettagliata per capire gli effetti dell'impatto della missione NASA DART sulla luna asteroidale Dimorphos, avvenuto nel 2022. Lo riferiscono Astronomy Now e Phys.org.",
   "more": [
    "La missione DART della NASA ha testato nel 2022 la possibilità di deviare un asteroide tramite impatto cinetico, colpendo deliberatamente Dimorphos. La sonda europea Hera è stata lanciata successivamente per studiare nel dettaglio le conseguenze dell'impatto, fornendo dati utili per future strategie di difesa planetaria."
   ],
