   "id": "z087da3dd",
   "sez": "ingegneria",
   "titolo": "Un hotel in Cina nasce dal recupero di baite abbandonate",
   "orig": "RooMoo transforms abandoned mountain cabins into hotel in China",
   "lead": "Lo studio RooMoo ha progettato un albergo di 24 camere sul monte Jinfo, nella municipalità di Chongqing, in Cina, utilizzando materiali recuperati da baite di montagna abbandonate. Il progetto impiega carote di cemento estratte da perforazioni, mattoni scartati e legname di recupero per costruire la struttura. L'intervento punta a dare nuova vita a edifici dismessi riducendo l'uso di materiali nuovi. Lo riferisce Dezeen.",
   "more": [
    "Il riuso di materiali da demolizione in architettura è una pratica sempre più diffusa per ridurre l'impatto ambientale delle costruzioni, specie in contesti montani dove il trasporto di nuovi materiali è costoso e impattante."
   ],
