   "sez": "mondo",
   "titolo": "Rissa ad Abu Dhabi tra il russo Nurmagomedov e il georgiano Dvalishvili",
   "orig": "Brawl Erupts After Russian MMA Fighter Nurmagomedov Slaps Georgian Merab Dvalishvili in Abu Dhabi",
   "lead": "Una rissa è scoppiata ad Abu Dhabi l'11 novembre dopo che il lottatore russo di MMA Usman Nurmagomedov, accompagnato da un gruppo di persone, si è avvicinato da dietro all'ex campione UFC georgiano Merab Dvalishvili e lo ha colpito con uno schiaffo mentre questi rilasciava un'intervista nella hall di un hotel. Le immagini mostrano Dvalishvili e il connazionale Saba Lazishvili, 21 anni, reagire pur essendo in minoranza numerica. Le autorità hanno interrogato i coinvolti; secondo alcune indiscrezioni Nurmagomedov potrebbe affrontare un fermo e accuse penali.",
   "more": [
    "Usman Nurmagomedov è un lottatore di MMA originario del Daghestan, regione russa a tradizione sportiva nelle arti marziali. Merab Dvalishvili è un atleta georgiano, ex campione dei pesi gallo UFC, molto popolare in patria. L'episodio si inserisce in un contesto di rivalità sportive tra atleti di diverse nazionalità del Caucaso."
   ],
