   "titolo": "Negli Usa la domanda dei data center spinge nuovi gasdotti mentre le regole si allentano",
   "orig": "US datacenter demand spurs increased fossil fuel pipeline projects as rules are discarded",
   "lead": "Un nuovo rapporto dell'Environmental Integrity Project mostra che negli Stati Uniti la crescente domanda di energia dei data center sta alimentando un'ondata di nuovi progetti di gasdotti, in un momento in cui l'amministrazione Trump ha smantellato regole che proteggono da possibili disastri lungo le condutture. Il rapporto segnala inoltre che nuovi gasdotti vengono costruiti per soddisfare la domanda di esportazioni di gas naturale, alimentata dai conflitti in Ucraina e in Iran. Lo riferisce The Guardian.",
   "more": [
    "I data center necessari per far funzionare l'intelligenza artificiale e i servizi digitali consumano grandi quantità di energia elettrica. Negli Stati Uniti questo ha spinto investimenti in infrastrutture per il gas naturale, mentre la deregolamentazione ambientale sotto l'amministrazione Trump ha ridotto i controlli sulla sicurezza delle pipeline."
   ],
