   "id": "zbc8c1040",
   "sez": "economia",
   "titolo": "Il Kazakhstan firma accordi energetici per 1,2 miliardi di dollari alla Cop31",
   "orig": "Kazakhstan Signs $1.2 Billion in Energy Agreements at COP31",
   "lead": "Il Kazakhstan ha firmato accordi per circa 1,2 miliardi di dollari destinati a sviluppare energie rinnovabili e modernizzare le infrastrutture del gas, durante il summit sul clima Cop31 ad Antalya, in Turchia. Gli accordi prevedono la costruzione di impianti eolici con una capacità di 150 megawatt nella regione del Turkistan e di un gigawatt nella regione di Kostanai. Lo riferiscono The Astana Times e AKIpress.",
   "more": [
    "La Cop31 è la conferenza delle Nazioni Unite sui cambiamenti climatici. Il Kazakhstan, grande produttore di combustibili fossili, sta cercando di diversificare il proprio mix energetico investendo in impianti eolici e nella modernizzazione delle reti del gas."
   ],
