   "titolo": "Negli Usa un'onda democratica attenua, per ora, il calo dei parlamentari neri alla Camera",
   "orig": "A blue wave helped offset for now a falling tally of Black members in the U.S. House",
   "lead": "Una sentenza della Corte Suprema degli Stati Uniti che ha ulteriormente indebolito il Voting Rights Act ha aperto la strada a un calo record della rappresentanza nera al Congresso. Tuttavia, un'onda favorevole ai democratici alle elezioni di metà mandato ha contribuito a contenere, almeno per ora, questo declino. Lo riferisce NPR.",
   "more": [
    "Il Voting Rights Act è una legge statunitense del 1965 che protegge il diritto di voto delle minoranze, in particolare contro pratiche discriminatorie nella definizione dei collegi elettorali. Decisioni recenti della Corte Suprema ne hanno ridotto la portata, facilitando in alcuni stati la ridefinizione di distretti a scapito della rappresentanza delle minoranze."
   ],
