   "sez": "ingegneria",
   "titolo": "I ritardi nei lavori al Parlamento britannico fanno temere un incendio come quello di Notre-Dame",
   "orig": "Renovation delays pose \"Notre Dame-like\" fire risk for Houses of Parliament",
   "lead": "Un nuovo rapporto segnala che i ritardi nei lavori di ristrutturazione del Palazzo di Westminster, sede del Parlamento britannico, stanno aumentando il rischio di un incendio simile a quello che ha devastato la cattedrale di Notre-Dame a Parigi. Lo riferisce Dezeen.",
   "more": [
    "Il Palazzo di Westminster è un edificio storico risalente in gran parte al XIX secolo, noto per le difficoltà manutentive legate alla sua struttura antica. L'incendio di Notre-Dame nel 2019 ha riacceso l'attenzione internazionale sui rischi di incendio negli edifici storici."
   ],
