   "id": "zfe073c38",
   "sez": "ambiente",
   "titolo": "Cop31, Greta Thunberg: \"Nessuno verrà a salvarci\"",
   "orig": "Cop31 live: ‘No one is coming to rescue us,’ Greta Thunberg tells climate summit",
   "lead": "Alla Cop31, il summit delle Nazioni Unite sul clima in corso ad Antalya, in Turchia, l'attivista Greta Thunberg ha dichiarato che \"nessuno verrà a salvarci\", mentre leader mondiali tra cui il primo ministro britannico Andy Burnham intervengono nella terza giornata dei lavori. Il leader dei Verdi britannici Zack Polanski ha criticato il discorso di Burnham, definendolo \"bizzarro\" e dicendo di non essere rassicurato dalle sue parole, sottolineando che l'azione climatica si misura nei fatti e non nelle dichiarazioni. Lo riferisce The Guardian.",
   "more": [
    "La Cop31 è la conferenza annuale delle Nazioni Unite sui cambiamenti climatici, dove i governi negoziano impegni per ridurre le emissioni e affrontare la crisi climatica. Greta Thunberg è un'attivista svedese diventata simbolo del movimento globale per il clima dal 2018."
   ],
