   "id": "z2e22e667",
   "sez": "salute",
   "titolo": "Regno Unito, cosa cambia nelle linee guida Prevent contro la radicalizzazione",
   "orig": "Changes to Prevent guidance on radicalisation: what you need to know",
   "lead": "Nel Regno Unito sono in corso modifiche alle linee guida del programma Prevent, parte della strategia antiterrorismo britannica Contest basata sulla legge del 2015 sulla sicurezza e il contrasto al terrorismo. Prevent mira a identificare e intervenire su persone a rischio di radicalizzazione prima che commettano atti violenti. Chi lavora nel settore sanitario ha il dovere di conoscere il programma e sapere come agire se un paziente appare a rischio. Lo riferisce The BMJ.",
   "more": [
    "Prevent è un programma britannico nato per individuare precocemente segnali di radicalizzazione violenta, coinvolgendo scuole, servizi sociali e sanità. È stato oggetto di critiche per il rischio di stigmatizzare alcune comunità, mentre i sostenitori lo considerano uno strumento di prevenzione necessario."
   ],
