   "id": "z7044f3e7",
   "sez": "mondo",
   "titolo": "In Texas i genitori preoccupati per l'istruzione hanno contribuito a far vincere i democratici",
   "orig": "How angry parents helped flip Texas: choosing real education over culture wars",
   "lead": "In Texas, genitori preoccupati per le politiche scolastiche hanno contribuito a spostare il voto verso i democratici alle elezioni per il consiglio statale dell'istruzione. Secondo quanto riporta The Guardian, misure come l'esposizione dei Dieci Comandamenti nelle classi, la revisione dei contenuti storici e lo studio di versetti biblici hanno spinto molti elettori, prima non politicamente attivi, a mobilitarsi. Michelle Palmer, candidata al consiglio per la seconda volta, ha raccontato di aver ricevuto fin dal primo giorno segnalazioni di persone preoccupate per l'istruzione dei figli.",
   "more": [
    "Negli Stati Uniti i consigli scolastici statali e locali hanno un peso significativo nella definizione dei programmi educativi. Negli ultimi anni in diversi stati a guida repubblicana, tra cui il Texas, sono state introdotte misure legate a contenuti religiosi o alla revisione dei programmi di storia, spesso al centro di controversie politiche."
   ],
