   "titolo": "Roma, allerta gialla per pioggia e vento con temperature sopra la media",
   "orig": "Meteo Roma, allerta gialla per piogge e vento (ma le temperature sono più alte della media)",
   "lead": "La Protezione civile ha diramato un'allerta meteo gialla per Roma per giovedì 12 novembre, a causa di piogge e vento legati a una perturbazione che ha già interessato alcune zone della città nelle prime ore del giorno. Nonostante l'allerta, le temperature nella Capitale risultano più alte della media stagionale. Lo riferisce Il Messaggero.",
