   "sez": "ambiente",
   "titolo": "Gli strike sulle navi nel Golfo causano chiazze di petrolio visibili dallo spazio",
   "orig": "Oil slicks seen from space: the devastating impact of boat strikes on fragile Gulf ecosystems",
   "lead": "Dall'inizio della guerra degli Stati Uniti contro l'Iran a febbraio, centinaia di sversamenti di petrolio hanno colpito il Golfo Persico dopo attacchi a petroliere con missili o mine marine nello stretto di Hormuz. Le macchie scure prodotte sono visibili dallo spazio e si sono diffuse lungo le coste, minacciando in modo \"generazionale\" la fauna marina, tra cui delfini e tartarughe. Secondo il New York Times, ripreso da Egypt Independent, l'amministrazione Trump avrebbe inoltre esercitato pressioni su società satellitari commerciali per impedire la diffusione di immagini ad alta risoluzione delle zone di conflitto. Lo riferisce The Guardian.",
   "more": [
    "Lo stretto di Hormuz è una via marittima strategica per il trasporto globale di petrolio. Gli sversamenti di idrocarburi in mare possono avere effetti duraturi sugli ecosistemi costieri, danneggiando la fauna marina e le comunità che dipendono dalla pesca."
   ],
