   "lead": "Il pilota di Formula 1 Kimi Antonelli, neo campione del mondo, è stato accolto con affetto dai tifosi al suo arrivo a una conferenza stampa a San Marino. Il pilota bolognese aveva promesso di tingersi i capelli tricolore in caso di vittoria del titolo e si è presentato così anche alla sede del team Mercedes a Brackley, sorprendendo il team principal Toto Wolff. Lo riferiscono San Marino RTV e Sky TG24.",
