   "id": "zb15b4f30",
   "sez": "adolescenti",
   "titolo": "Libriamoci 2027, Ugo Foscolo al centro delle giornate di lettura nelle scuole",
   "orig": "Libriamoci 2027, Ugo Foscolo ispira il tema delle giornate di lettura nelle scuole dal 15 al 20 febbraio: iscrizioni dal 14 dicembre",
   "lead": "Dal 15 al 20 febbraio 2027 torna \"Libriamoci. Giornate di lettura nelle scuole\", la campagna nazionale italiana dedicata a promuovere la lettura ad alta voce tra gli studenti di ogni ordine e grado. L'edizione di quest'anno è ispirata alla figura di Ugo Foscolo. Le iscrizioni per le scuole interessate a partecipare apriranno il 14 dicembre. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Libriamoci è un'iniziativa promossa dal ministero della Cultura e dal ministero dell'Istruzione italiani per avvicinare gli studenti alla lettura attraverso momenti condivisi in classe, con il coinvolgimento di scrittori, insegnanti e altre figure educative."
   ],
