   "id": "zc4d97ee5",
   "sez": "mondo",
   "titolo": "La junta birmana chiede un bilancio militare record mentre milioni di persone vivono in povertà",
   "orig": "Myanmar Junta Seeks Record Military Budget as Millions Struggle With Poverty",
   "lead": "Il regime militare del Myanmar ha richiesto per il 2026-27 un bilancio della Difesa di 10,53 trilioni di kyat, oltre tre volte superiore al livello precedente al colpo di stato, mentre quasi 18 milioni di persone nel Paese vivono in povertà. Lo riferisce The Irrawaddy. La stessa junta ha inoltre ammesso, secondo Myanmar Now, che una fornitura elettrica affidabile per 24 ore al giorno resta un obiettivo lontano, da raggiungere solo al completamento di progetti energetici come l'impianto nucleare russo in costruzione da un decennio.",
   "more": [
    "Il Myanmar è governato da una junta militare dal colpo di stato del 2021, che ha destabilizzato l'economia del Paese e aggravato la povertà. Il forte aumento della spesa militare, in un contesto di crisi economica e infrastrutturale, è spesso indicato come segno delle priorità del regime nella gestione dei conflitti interni in corso."
   ],
