   "titolo": "Fotografie inedite di Carmelo Bene ritrovate nei mercatini di Roma, in mostra al Macro",
   "orig": "Carmelo Bene inedito al Macro di Roma: le foto ritrovate nei mercatini",
   "lead": "Un fondo di fotografie inedite dedicate all'attore e regista Carmelo Bene, recuperate tra le bancarelle del mercato di Porta Portese a Roma, sarà esposto al museo Macro della capitale. Gli scatti, trovati accatastati su teli o direttamente sull'asfalto durante le contrattazioni notturne tipiche del mercatino romano, documentano momenti della vita artistica del celebre interprete salentino. La notizia arriva dalla redazione culturale che ha raccontato il percorso di recupero di questi materiali fotografici, finiti per anni dimenticati tra gli oggetti di seconda mano prima di essere identificati e valorizzati. Lo riferisce Il Messaggero.",
   "more": [
    "Carmelo Bene (1937-2002) è stato uno dei più importanti e sperimentali attori, regista teatrale e cinematografico italiani del secondo Novecento, noto per la sua rilettura radicale dei classici e per uno stile interpretativo fortemente personale e anticonformista."
   ],
