   "id": "ze67e60bf",
   "sez": "mondo",
   "titolo": "Singapore lancia un tirocinio per avvicinare i giovani al mestiere di venditore ambulante",
   "orig": "New internship programme aims to draw more young Singaporeans into hawker trade",
   "lead": "A Singapore partirà ad aprile 2027 un nuovo programma di tirocinio destinato a studenti degli istituti ITE e del Temasek Polytechnic, che potranno fare esperienza pratica nei banchi di cibo di strada (hawker). L'iniziativa fa parte degli sforzi delle autorità per preservare la cultura degli hawker, elemento identitario della città-stato, cercando di attirare nuove generazioni verso un mestiere tradizionalmente poco attraente per i giovani. Lo riferisce CNA.",
   "more": [
    "La cultura hawker di Singapore, riconosciuta patrimonio culturale immateriale dall'UNESCO nel 2020, riunisce centri di ristorazione di strada con cibo economico e vario. Negli ultimi anni il settore fatica a trovare nuove generazioni disposte a proseguire l'attività dei genitori o nonni venditori."
   ],
