   "id": "z7ac389e9",
   "sez": "tech",
   "titolo": "Moldova, fino a 10 anni di carcere per attacchi informatici alle infrastrutture critiche",
   "orig": "Cyberattacks on critical infrastructure could carry prison sentences of up to 10 years",
   "lead": "In Moldova gli attacchi informatici contro infrastrutture critiche, inclusi i sistemi dei settori energia, sanità, trasporti e banche, saranno classificati come reati aggravati e potranno comportare pene fino a dieci anni di carcere. La misura punta a rafforzare la protezione dei servizi essenziali del paese dalle minacce cibernetiche, in un contesto di crescente attenzione europea alla sicurezza delle reti informatiche strategiche. Lo riferisce IPN.",
   "more": [
    "Le infrastrutture critiche comprendono i sistemi essenziali per il funzionamento di uno Stato, come energia, acqua, sanità e trasporti. Gli attacchi informatici contro questi settori sono considerati particolarmente gravi perché possono causare danni diffusi alla popolazione e sono oggetto di normative sempre più severe in Europa."
   ],
