   "id": "za7ec54a0",
   "sez": "salute",
   "titolo": "Arusha rafforza le cure d'emergenza per promuovere il turismo medico",
   "orig": "Arusha steps up emergency care to boost medical tourism",
   "lead": "Il governo della regione di Arusha, in Tanzania, sta rafforzando i servizi medici di emergenza per migliorare la sicurezza di residenti, turisti e partecipanti a conferenze, puntando a posizionare l'area come polo di turismo medico. Lo ha dichiarato il commissario distrettuale di Arumeru, Neema Lugangira, in rappresentanza del commissario regionale Amos Makalla, spiegando che sono previsti investimenti in infrastrutture sanitarie, apparecchiature mediche e servizi specialistici per elevare la qualità dell'assistenza offerta. Lo riferisce Daily News (Tanzania).",
   "more": [
    "Il turismo medico consiste nello spostarsi in un altro paese per ricevere cure sanitarie, spesso a costi inferiori o con servizi non disponibili in patria. Diverse nazioni africane puntano a sviluppare questo settore come fonte di entrate economiche aggiuntive."
   ],
