   "id": "zec51d59b",
   "sez": "mondo",
   "titolo": "Hong Kong, 10 arresti per biglietti falsi di concerti e riciclaggio di denaro",
   "orig": "10 arrested in fake concert ticket crackdown",
   "lead": "La polizia di Hong Kong ha arrestato dieci persone, tra i 18 e i 46 anni, in un'operazione di due giorni contro la vendita di biglietti falsi per concerti e il relativo riciclaggio di denaro. Secondo gli investigatori, conti bancari usati come prestanome collegati ai casi avrebbero gestito oltre 81 milioni di dollari di Hong Kong provenienti da proventi di reato sospetti. Il gruppo, descritto come organizzato e sistematico dall'ispettore capo Chung Man-ning, è accusato di associazione per truffa, ottenimento di beni con l'inganno e riciclaggio. Lo riferisce RTHK.",
   "more": [
    "Le truffe sui biglietti falsi per eventi musicali sono un fenomeno diffuso che sfrutta la domanda elevata per concerti popolari, spesso tramite siti o canali social non ufficiali. I proventi vengono talvolta fatti transitare su conti di terzi per occultarne l'origine, pratica nota come riciclaggio tramite \"muli\" bancari."
   ],
