   "id": "zf30aede0",
   "sez": "mondo",
   "titolo": "Tripoli valuta soluzioni radicali, incluso un monorail, per la congestione del traffico",
   "orig": "Radical solutions, including monorail, considered to address Tripoli's acute traffic congestion",
   "lead": "Il Ministero dei Trasporti libico ha tenuto una riunione per discutere misure contro la grave congestione del traffico a Tripoli, secondo quanto dichiarato in esclusiva a Libya Herald da un funzionario del ministero. Tra le soluzioni allo studio figura la realizzazione di un sistema di monorotaia. L'incontro si inserisce in un più ampio sforzo di pianificazione urbana per affrontare un problema diffuso in molte capitali, come dimostrano iniziative simili ad Ho Chi Minh City e Bishkek, dove autorità locali stanno parallelamente cercando risposte alla congestione stradale. Lo riferisce Libya Herald.",
   "more": [
    "La congestione del traffico urbano è un problema comune a molte città in rapida crescita, spesso legato a infrastrutture stradali insufficienti rispetto all'aumento dei veicoli. Sistemi di trasporto di massa come monorotaie o metropolitane sono soluzioni frequentemente proposte per decongestionare i centri urbani."
   ],
