   "id": "zde626235",
   "sez": "mondo",
   "titolo": "Algeria, lo scrittore Kamel Daoud condannato a 5 anni di carcere nel caso \"Houris\"",
   "orig": "Kamel Daoud condamné à 5 ans de prison en Algérie dans l’affaire « Houris »",
   "lead": "Lo scrittore franco-algerino Kamel Daoud e la psichiatra Aïcha Dahdouh sono stati condannati in Algeria a cinque anni di carcere e a una multa di 300.000 dinari ciascuno. La sentenza, pronunciata martedì 10 novembre dal tribunale correttivo di Fellaoucène, a Orano, riguarda una denuncia della donna Saâda Arbane, che sostiene che il romanzo di Daoud si ispiri alla sua storia personale senza il suo consenso. I due condannati contestano le accuse. Lo riferisce Le Matin Algérie.",
   "more": [
    "Kamel Daoud è un noto scrittore e giornalista franco-algerino, vincitore del premio Goncourt 2024 con il romanzo \"Houris\", incentrato sulla guerra civile algerina degli anni Novanta. Il caso giudiziario riguarda accuse di appropriazione della storia personale di una vittima reale di quel conflitto senza autorizzazione."
   ],
