   "titolo": "Nigeria, organizzazioni chiedono il rilascio del giornalista Daniel Ojukwu",
   "orig": "CSOs condemn remand of journalist Daniel Ojukwu, demand immediate release",
   "lead": "Diciassette organizzazioni della società civile e dei media hanno condannato la detenzione del giornalista investigativo nigeriano Daniel Ojukwu, trattenuto in carcere dopo reportage che mettevano in discussione la spesa pubblica. Le organizzazioni chiedono il suo rilascio immediato e la fine della criminalizzazione del giornalismo investigativo in Nigeria. Il caso si inserisce in un contesto di crescente attenzione internazionale sulla libertà di stampa nel paese e sulle pressioni giudiziarie contro i reporter che indagano su temi sensibili legati alla gestione dei fondi pubblici. Lo riferisce Premium Times.",
   "more": [
    "Il giornalismo investigativo in Nigeria affronta spesso pressioni legali e detenzioni legate a reportage su corruzione e gestione delle risorse pubbliche. Organizzazioni internazionali per la libertà di stampa monitorano regolarmente questi casi come indicatori dello stato della libertà di espressione nel paese."
   ],
