   "titolo": "Anche il Belgio sospetta l'Iran dietro il cyberattacco ai sistemi di refrigerazione",
   "orig": "Ook België heeft aanwijzingen dat Iran achter cyberaanval op koelsystemen zit",
   "lead": "Dopo la Francia, anche il Belgio ha indicazioni che l'Iran sia coinvolto nei recenti attacchi informatici ai sistemi di refrigerazione in diversi paesi europei, che all'inizio del mese hanno costretto decine di negozi belgi a buttare grandi quantità di cibo. Secondo il ministro dell'Interno e della Sicurezza Quintin, i servizi di sicurezza belgi hanno indizi del coinvolgimento di gruppi di hacker legati all'Iran, come riportato dall'emittente fiamminga VRT. Lo riferiscono NOS e NRC.",
   "more": [
    "I sistemi di refrigerazione industriale, spesso collegati a reti informatiche per il monitoraggio remoto, sono diventati bersaglio di attacchi cyber capaci di causare danni materiali concreti, come la perdita di grandi quantità di alimenti. Attribuire questi attacchi a Stati è complesso e richiede analisi tecniche approfondite condotte dai servizi di intelligence."
   ],
